import { createHash } from "node:crypto";
import { generateVoidAndCluster, VOID_CLUSTER_SIGMA } from "./void-and-cluster";

const seed = 0x5eed1234;
const lines = [
  "// Generated by bun run generate:blue-noise. Do not edit by hand.",
  "// Offline void-and-cluster ranks, packed as little-endian uint16.",
  "export const PRECOMPUTED_BLUE_NOISE_SEED = 0x5eed1234;",
  "export const precomputedBlueNoise: Readonly<Record<number, string>> = {",
];
const tiles: { size: number; relaxationSwaps: number; sha256: string }[] = [];
for (const size of [64, 128, 256]) {
  const start = performance.now();
  const { ranks, relaxationSwaps } = generateVoidAndCluster(size, seed);
  const bytes = new Uint8Array(ranks.length * 2);
  const view = new DataView(bytes.buffer);
  ranks.forEach((rank, index) => view.setUint16(index * 2, rank, true));
  lines.push(`  ${size}: "${Buffer.from(bytes).toString("base64")}",`);
  tiles.push({
    size,
    relaxationSwaps,
    sha256: createHash("sha256").update(bytes).digest("hex"),
  });
  console.log(
    `${size}×${size}: ${relaxationSwaps} relaxation swaps, ${ranks.length} progressive ranks, ${Math.round(performance.now() - start)} ms`,
  );
}
lines.push("};", "");
await Bun.write(
  new URL("../src/blueNoisePatterns.ts", import.meta.url),
  lines.join("\n"),
);
await Bun.write(
  new URL("../tests/blue-noise-metadata.json", import.meta.url),
  JSON.stringify(
    { algorithm: "void-and-cluster", sigma: VOID_CLUSTER_SIGMA, seed, tiles },
    null,
    2,
  ) + "\n",
);
